#if swift(>=5.8)
@_documentation(visibility: private)
#endif
fileprivate struct FfiConverterTimestamp: FfiConverterRustBuffer {
    typealias SwiftType = Date

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Date {
        let seconds: Int64 = try readInt(&buf)
        let nanoseconds: UInt32 = try readInt(&buf)
        // Build the Date from whole seconds first, then add the nanoseconds as a
        // separate TimeInterval.  Date stores CFAbsoluteTime (seconds since 2001),
        // so adding a small fraction to the ~7.8e8 base is twice as precise as
        // adding it to the ~1.76e9 Unix-epoch value, because the smaller magnitude
        // leaves more mantissa bits for the sub-second part.
        if seconds >= 0 {
            return Date(timeIntervalSince1970: Double(seconds))
                .addingTimeInterval(Double(nanoseconds) / 1.0e9)
        } else {
            return Date(timeIntervalSince1970: Double(seconds))
                .addingTimeInterval(-Double(nanoseconds) / 1.0e9)
        }
    }

    public static func write(_ value: Date, into buf: inout [UInt8]) {
        var delta = value.timeIntervalSince1970
        var sign: Int64 = 1
        if delta < 0 {
            // The nanoseconds portion of the epoch offset must always be
            // positive, to simplify the calculation we will use the absolute
            // value of the offset.
            sign = -1
            delta = -delta
        }
        if delta.rounded(.down) > Double(Int64.max) {
            fatalError("Timestamp overflow, exceeds max bounds supported by Uniffi")
        }
        let seconds = Int64(delta)
        let nanoseconds = UInt32((delta - Double(seconds)) * 1.0e9)
        writeInt(&buf, sign * seconds)
        writeInt(&buf, nanoseconds)
    }
}




public protocol AsperoProtocol: AnyObject, Sendable {
    
    /**
     * Works as BibTeX entries (keys kept distinct) or RIS records, one
     * after another, or as a CSL-JSON array (keyed as BibTeX). Offline.
     */
    func export(works: [Work], format: ExportFormat)  -> String
    
    /**
     * The citations Zotero or Mendeley keep in a Word document (.docx),
     * each work once as a claim to verify, and the document's text.
     * Throws `ReadError.Unrecognised` for anything but a .docx file.
     * Offline.
     */
    func readDocx(data: Data) throws  -> DocxReferences
    
    /**
     * A BibTeX/BibLaTeX, RIS or CSL-JSON file's entries, each a claim to
     * verify; the format is told from the contents. Offline.
     */
    func readReferences(text: String) throws  -> Bibliography
    
    /**
     * The bundled citation styles: APA, Vancouver, Harvard, Chicago,
     * IEEE, Nature, AMA, MLA.
     */
    func citationStyles()  -> [CitationStyle]
    
    /**
     * Works as a reference list in `style`, one entry each, in the
     * style's order (alphabetical, or as given). `locale` (`en-GB`) sets
     * the language of terms like "et al."; by default, the style's own.
     * Offline.
     */
    func cite(works: [Work], style: StyleSource, format: CiteFormat, locale: String?) throws  -> [CitedEntry]
    
    /**
     * The bundled styles' and locales' license (CC BY-SA 3.0) and
     * authors, to show with formatted references.
     */
    func styleCredits()  -> String
    
    /**
     * The project the bundled styles and locales come from (the Citation
     * Style Language), their licence, and the locales. Offline.
     */
    func styleProject()  -> StyleProject
    
    /**
     * The free copy of `work`, for an app about to fetch it: its open
     * access, with a PDF a program can fetch where PubMed Central's open
     * data has one. Asks PMC's open data
     * (`pmc-oa-opendata.s3.amazonaws.com`, sending only the PMCID: two
     * requests, one when PMC hasn't the article) when the work has a
     * PMCID and no fetchable PDF; nothing for other works. `lookup` never
     * asks, even with `full`. Cached like lookups.
     */
    func freeCopy(work: Work, patience: Patience, cancel: CallToken?) async throws  -> FreeCopy
    
    /**
     * Analyses of the set of works `seeds` names (identifiers as
     * written): retracted references, odd ones out, probably missing
     * works, and related works (the best `related_limit` around the set,
     * by co-citation and coupling). Each seed resolves cheaply (asked
     * once) or says why not; paid requests stop before `budget_usd` would
     * be passed, and what stopped says how far it got. With
     * `estimate_only`, nothing paid is asked: `estimate` says what a run
     * would cost.
     */
