    typealias FfiType = UInt64
    typealias SwiftType = McpHoldings

    public static func lift(_ handle: UInt64) throws -> McpHoldings {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return McpHoldingsImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: McpHoldings) -> UInt64 {
