/**
 * Analyses of a set of works.
 */
public struct Analysis: Equatable, Hashable {
    /**
     * One per seed given, in order.
     */
    public var seeds: [Seed]
    /**
     * Works of the set (seeds merged) with known references: what "cited
     * by k of n" counts out of.
     */
    public var withReferences: UInt32
    public var retractedReferences: RetractedReferences?
    public var oddOneOut: OddOnesOut?
    public var probablyMissing: ProbablyMissing?
    /**
     * With `estimateOnly`: the cost of running it, in place of findings.
     */
    public var estimate: Estimate?
    /**
     * Every seed settled and every analysis run to the end.
     */
    public var complete: Bool
    /**
     * What stopped resolving the seeds early; empty when nothing did.
     */
    public var incomplete: [Incomplete]
    /**
     * Why there's no analysis at all (no OpenAlex).
     */
    public var failure: Failure?
    public var usage: [ProviderUsage]
    /**
     * Works around the set, when asked for (`related`).
     */
    public var related: RelatedWorks?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * One per seed given, in order.
         */seeds: [Seed], 
        /**
         * Works of the set (seeds merged) with known references: what "cited
         * by k of n" counts out of.
         */withReferences: UInt32, retractedReferences: RetractedReferences?, oddOneOut: OddOnesOut?, probablyMissing: ProbablyMissing?, 
        /**
         * With `estimateOnly`: the cost of running it, in place of findings.
         */estimate: Estimate?, 
        /**
         * Every seed settled and every analysis run to the end.
         */complete: Bool, 
        /**
         * What stopped resolving the seeds early; empty when nothing did.
         */incomplete: [Incomplete], 
        /**
         * Why there's no analysis at all (no OpenAlex).
         */failure: Failure?, usage: [ProviderUsage], 
        /**
         * Works around the set, when asked for (`related`).
         */related: RelatedWorks? = nil) {
        self.seeds = seeds
        self.withReferences = withReferences
        self.retractedReferences = retractedReferences
        self.oddOneOut = oddOneOut
        self.probablyMissing = probablyMissing
        self.estimate = estimate
        self.complete = complete
        self.incomplete = incomplete
        self.failure = failure
        self.usage = usage
        self.related = related
    }

    

    
}

