/**
 * One claim's verification.
 */
public struct Verification: Equatable, Hashable {
    /**
     * The claim's position in the call's `claims`.
     */
    public var index: UInt32
    /**
     * The claim's text, or its fields on one line.
     */
    public var input: String
    /**
     * The claim's `key`.
     */
    public var claimKey: String?
    public var verdict: Verdict
    /**
     * Why, as data, for the app to word.
     */
    public var reason: Reason
    /**
     * One sentence in English, `reason` and `notices`: for logs and agents,
     * not for display in an app UI.
     */
    public var reasonText: String
    /**
     * About `bestMatch`, whatever the verdict: its retraction or
     * withdrawal, and its newer version.
     */
    public var notices: [Notice]
    /**
     * The claim as read: identifiers as written (with the other readings
     * tried in `alternativeIds`), and from free text the year, journal
     * (`container`, where it can be told), volume, first page, and the
     * title and authors as written: where `bestMatch`'s title stands in
     * it, else where the layout tells them; empty where it can't be told.
     * `nil` for an invalid claim.
     */
    public var read: Claim?
    /**
     * The work the verdict is about: the match, or the best guess.
     */
    public var bestMatch: Candidate?
    /**
     * With `full`: every candidate, most confident first.
     */
    public var candidates: [Candidate]
    /**
     * Providers that failed, searching or looking up the claim's
     * identifiers; what they'd have found is unknown.
     */
    public var errors: [Failure]
    /**
     * Whether the claim's `site` decided which work `bestMatch` is: of
     * works matching about as well, the page's publisher's ("chosen as
     * the page's publisher's"). It never changes the verdict.
     */
    public var chosenBySite: Bool
    /**
     * `reason` as stored data: stable, versioned JSON (the JSON
     * contract's `reason`, with `v`), read back with `reasonFromJson`. For
     * an app that keeps verifications and words their reasons when shown.
     */
    public var reasonJson: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The claim's position in the call's `claims`.
         */index: UInt32, 
        /**
         * The claim's text, or its fields on one line.
         */input: String, 
        /**
         * The claim's `key`.
         */claimKey: String?, verdict: Verdict, 
        /**
         * Why, as data, for the app to word.
         */reason: Reason, 
        /**
         * One sentence in English, `reason` and `notices`: for logs and agents,
         * not for display in an app UI.
         */reasonText: String, 
        /**
         * About `bestMatch`, whatever the verdict: its retraction or
         * withdrawal, and its newer version.
         */notices: [Notice], 
        /**
         * The claim as read: identifiers as written (with the other readings
         * tried in `alternativeIds`), and from free text the year, journal
         * (`container`, where it can be told), volume, first page, and the
         * title and authors as written: where `bestMatch`'s title stands in
         * it, else where the layout tells them; empty where it can't be told.
         * `nil` for an invalid claim.
         */read: Claim?, 
        /**
         * The work the verdict is about: the match, or the best guess.
         */bestMatch: Candidate?, 
        /**
         * With `full`: every candidate, most confident first.
         */candidates: [Candidate], 
        /**
         * Providers that failed, searching or looking up the claim's
         * identifiers; what they'd have found is unknown.
         */errors: [Failure], 
        /**
         * Whether the claim's `site` decided which work `bestMatch` is: of
         * works matching about as well, the page's publisher's ("chosen as
         * the page's publisher's"). It never changes the verdict.
         */chosenBySite: Bool = false, 
        /**
         * `reason` as stored data: stable, versioned JSON (the JSON
         * contract's `reason`, with `v`), read back with `reasonFromJson`. For
         * an app that keeps verifications and words their reasons when shown.
         */reasonJson: String = "") {
        self.index = index
        self.input = input
        self.claimKey = claimKey
        self.verdict = verdict
        self.reason = reason
        self.reasonText = reasonText
        self.notices = notices
        self.read = read
        self.bestMatch = bestMatch
        self.candidates = candidates
        self.errors = errors
        self.chosenBySite = chosenBySite
        self.reasonJson = reasonJson
    }

    

    
}

