        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .retractedReferences
        
        case 2: return .oddOneOut
        
        case 3: return .probablyMissing(limit: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 4: return .related
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AnalysisKind, into buf: inout [UInt8]) {
        switch value {
        
        
