     * A bug: the call panicked or its task was lost.
     */
    case Internal(message: String)
    
    /**
     * The cache file couldn't be read or written.
     */
    case Cache(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
