/**
 * Why a verdict was reached. "The work" is the verification's `bestMatch`;
 * "the identifiers" are those the claim gave.
 */

public enum Reason: Equatable, Hashable {
    
    /**
     * The citation matches the work.
     */
    case matches
    /**
     * Never empty.
     */
    case partlyMatches(differs: [Difference]
    )
    /**
     * The citation agrees with the work as far as it goes, but gives too
     * little to confirm it.
     */
    case unconfirmed
    /**
     * The closest work shares the title, but other details differ.
     * Never empty.
     */
    case closest(differs: [Difference]
    )
    case noMatch
    /**
     * The identifiers exist; the claim gives nothing else to compare.
     */
    case idExists
    /**
     * The identifiers exist and the citation agrees.
     */
    case idAgrees
    /**
     * Never empty.
     */
    case idPartlyMatches(differs: [Difference]
    )
    /**
     * The identifiers are `cited`; the citation matches the work.
     */
    case idElsewhere(cited: Candidate
    )
    /**
     * The identifiers' work (the work) doesn't match the citation, and no
     * other does.
     */
    case idDisagrees
    /**
     * The identifiers don't exist; the citation matches the work.
     */
    case idMissingElsewhere
    case idMissing
    case providersFailed
    /**
     * The claim couldn't be read; `why` in English.
     */
    case invalidClaim(why: String
    )
    /**
     * aspero itself failed on this claim (a bug, caught so the rest of a
     * batch goes on); the verification's `reason_text` has the message.
     */
    case internalError





}

#if compiler(>=6)
extension Reason: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeReason: FfiConverterRustBuffer {
    typealias SwiftType = Reason

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Reason {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .matches
        
        case 2: return .partlyMatches(differs: try FfiConverterSequenceTypeDifference.read(from: &buf)
        )
        
        case 3: return .unconfirmed
        
        case 4: return .closest(differs: try FfiConverterSequenceTypeDifference.read(from: &buf)
        )
        
        case 5: return .noMatch
        
        case 6: return .idExists
        
        case 7: return .idAgrees
        
        case 8: return .idPartlyMatches(differs: try FfiConverterSequenceTypeDifference.read(from: &buf)
        )
        
        case 9: return .idElsewhere(cited: try FfiConverterTypeCandidate.read(from: &buf)
        )
        
        case 10: return .idDisagrees
        
        case 11: return .idMissingElsewhere
        
        case 12: return .idMissing
        
        case 13: return .providersFailed
        
        case 14: return .invalidClaim(why: try FfiConverterString.read(from: &buf)
        )
        
        case 15: return .internalError
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Reason, into buf: inout [UInt8]) {
        switch value {
        
        
        case .matches:
            writeInt(&buf, Int32(1))
        
        
        case let .partlyMatches(differs):
            writeInt(&buf, Int32(2))
            FfiConverterSequenceTypeDifference.write(differs, into: &buf)
            
        
        case .unconfirmed:
            writeInt(&buf, Int32(3))
        
        
        case let .closest(differs):
            writeInt(&buf, Int32(4))
            FfiConverterSequenceTypeDifference.write(differs, into: &buf)
            
        
        case .noMatch:
            writeInt(&buf, Int32(5))
        
        
        case .idExists:
            writeInt(&buf, Int32(6))
        
        
        case .idAgrees:
            writeInt(&buf, Int32(7))
        
        
        case let .idPartlyMatches(differs):
            writeInt(&buf, Int32(8))
            FfiConverterSequenceTypeDifference.write(differs, into: &buf)
            
        
        case let .idElsewhere(cited):
            writeInt(&buf, Int32(9))
            FfiConverterTypeCandidate.write(cited, into: &buf)
            
        
        case .idDisagrees:
            writeInt(&buf, Int32(10))
        
        
        case .idMissingElsewhere:
            writeInt(&buf, Int32(11))
        
        
        case .idMissing:
            writeInt(&buf, Int32(12))
        
        
        case .providersFailed:
            writeInt(&buf, Int32(13))
        
        
        case let .invalidClaim(why):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(why, into: &buf)
            
        
        case .internalError:
            writeInt(&buf, Int32(15))
        
        }
    }
}


