        switch variant {
        
        case 1: return .all(nodes: try FfiConverterSequenceTypeSearchNode.read(from: &buf)
        )
        
        case 2: return .any(nodes: try FfiConverterSequenceTypeSearchNode.read(from: &buf)
        )
        
