        )
        
        case 4: return .term(field: try FfiConverterTypeSearchField.read(from: &buf), value: try FfiConverterString.read(from: &buf), phrase: try FfiConverterBool.read(from: &buf)
        )
        
        case 5: return .filter(filter: try FfiConverterTypeSearchFilterValue.read(from: &buf)
        )
        
        case 6: return .relation(relation: try FfiConverterTypeSearchRelation.read(from: &buf), id: try FfiConverterString.read(from: &buf)
        )
        
